// TestRequireContentType_ChunkedEncoding_NoContentType verifies that
// RequireContentType still enforces the Content-Type header when the
// request uses chunked transfer encoding (ContentLength == -1).
// A request with an unknown content length but an actual body must
// still have a Content-Type header.
func TestRequireContentType_ChunkedEncoding_NoContentType(t *testing.T) {
	handler := middleware.RequireContentType(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusOK)
		w.Write([]byte("ok"))
	}))

	req := httptest.NewRequest("POST", "/test", strings.NewReader(`{"key":"value"}`))
	req.ContentLength = -1 // Simulate chunked transfer encoding (unknown length)
	// No Content-Type header set
	rr := httptest.NewRecorder()

	handler.ServeHTTP(rr, req)

	if rr.Code != http.StatusUnsupportedMediaType {
		t.Errorf("expected status %d for chunked request without Content-Type, got %d", http.StatusUnsupportedMediaType, rr.Code)
	}
}

// TestRequireContentTypeWithAllowed_ChunkedEncoding_NoContentType verifies that
// RequireContentTypeWithAllowed still enforces the Content-Type header when the
